import type { SafetyLevel } from "./classifier";

// Fixed responses for crisis-level messages. These are never generated by a
// language model. Wording must pass clinical review before public release.

export const CRISIS_RESPONSE = [
  "I'm really glad you told me. I mean that.",
  "What you're carrying right now matters, and you deserve to have a real person with you in it. I'm an AI, and this is more than I should be the only one holding.",
  "Please reach out now: you can call or text 988 to talk with someone at the Suicide & Crisis Lifeline, any hour. If you're in immediate danger, call 911.",
  "I'm still here with you. Are you safe right now?",
].join("\n\n");

export const HARM_TO_OTHERS_RESPONSE = [
  "Thank you for being honest with me. That took something.",
  "When anger or pain gets this strong, the most important thing is that nobody gets hurt, including you. If anyone is in immediate danger, call 911. You can also call or text 988 and talk it through with someone right now.",
  "I'm an AI, so I can't be the help you need in this moment, but I'm still here. Can you put some distance between yourself and the situation right now?",
].join("\n\n");

// Extra instructions appended to the system prompt when a message shows
// distress or an abuse disclosure. The model still responds, with care.
export function safetyInstructions(level: SafetyLevel): string | null {
  if (level === "distress") {
    return [
      "SAFETY CONTEXT: The man's latest message shows signs of significant distress.",
      "Slow down. Reflect what you hear before anything else. Do not give advice or action steps in this reply.",
      "Gently ask how he is doing right now, and whether he is safe.",
      "Mention, without pressure, that if things feel like too much he can call or text 988 any time.",
      "Do not diagnose. Do not minimise. Do not ask for details of painful memories.",
    ].join(" ");
  }
  if (level === "abuse") {
    return [
      "SAFETY CONTEXT: The man's latest message may disclose abuse, current or past.",
      "Believe him and thank him for telling you. Do not ask for details of what happened.",
      "If the abuse may be ongoing or a child may be at risk, ask whether he or anyone else is in danger right now, and mention that the app's Help page lists people who can help, and 911 for immediate danger.",
      "Make clear none of it was his fault if it happened to him. Do not offer legal conclusions.",
    ].join(" ");
  }
  return null;
}
